import{_ as t,o as a,c as o,a2 as l}from"./chunks/framework.Crpw6aS5.js";const u=JSON.parse('{"title":"管理层选择 Selecting Management","description":"跟对人，是投资成功的第一步","frontmatter":{"title":"管理层选择 Selecting Management","description":"跟对人，是投资成功的第一步"},"headers":[],"relativePath":"02_concepts/management.md","filePath":"02_concepts/management.md"}'),r={name:"02_concepts/management.md"};function h(p,e,n,s,i,m){return a(),o("div",null,[...e[0]||(e[0]=[l('<h1 id="管理层选择-selecting-management" tabindex="-1">管理层选择 Selecting Management <a class="header-anchor" href="#管理层选择-selecting-management" aria-label="Permalink to &quot;管理层选择 Selecting Management&quot;">​</a></h1><blockquote><p>&quot;在我挑选股票时，管理层的重要性占49%。&quot;<br> ——<a href="/04_people/沃伦·巴菲特.html">沃伦·巴菲特</a></p></blockquote><hr><h2 id="核心出处" tabindex="-1">核心出处 <a class="header-anchor" href="#核心出处" aria-label="Permalink to &quot;核心出处&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">年份</th><th style="text-align:left;">重点内容</th></tr></thead><tbody><tr><td style="text-align:left;"><strong><a href="/01_letters/1983年/核心总结.html">核心总结</a></strong></td><td style="text-align:left;">收购的是人，不是机器</td></tr><tr><td style="text-align:left;"><strong><a href="/01_letters/1995年/核心总结.html">核心总结</a></strong></td><td style="text-align:left;">管理层诚信与能力的重要性</td></tr><tr><td style="text-align:left;"><strong><a href="/01_letters/1998年/核心总结.html">核心总结</a></strong></td><td style="text-align:left;">&quot;关键人风险&quot;的警示</td></tr><tr><td style="text-align:left;"><strong><a href="/01_letters/2005年/核心总结.html">核心总结</a></strong></td><td style="text-align:left;">德才兼备的管理层标准</td></tr><tr><td style="text-align:left;"><strong><a href="/01_letters/2008年/核心总结.html">核心总结</a></strong></td><td style="text-align:left;">金融危机中对管理层的反思</td></tr><tr><td style="text-align:left;"><strong><a href="/01_letters/2015年/核心总结.html">核心总结</a></strong></td><td style="text-align:left;">继任规划与文化传承</td></tr></tbody></table><hr><h2 id="巴菲特论管理层-按年代梳理" tabindex="-1">巴菲特论管理层：按年代梳理 <a class="header-anchor" href="#巴菲特论管理层-按年代梳理" aria-label="Permalink to &quot;巴菲特论管理层：按年代梳理&quot;">​</a></h2><h3 id="_1970年代-找到出色经理人-让他们像所有者一样思考" tabindex="-1">1970年代｜找到出色经理人，让他们像所有者一样思考 <a class="header-anchor" href="#_1970年代-找到出色经理人-让他们像所有者一样思考" aria-label="Permalink to &quot;1970年代｜找到出色经理人，让他们像所有者一样思考&quot;">​</a></h3><p><a href="/04_people/沃伦·巴菲特.html">巴菲特</a>从早期投资开始，就深刻认识到优秀管理层对投资成败的决定性作用。1970年代，他反复强调：<strong>投资的核心不是买资产，而是买人</strong>。他开始系统性地寻找那些既有能力、又像所有者一样思考的管理者——他们不为短期业绩所驱动，而是真正把股东当作合伙人。</p><hr><h3 id="_1985年-关闭纺织业务——-错在我自己-应该早点关" tabindex="-1">1985年｜关闭纺织业务——&quot;错在我自己，应该早点关&quot; <a class="header-anchor" href="#_1985年-关闭纺织业务——-错在我自己-应该早点关" aria-label="Permalink to &quot;1985年｜关闭纺织业务——&quot;错在我自己，应该早点关&quot;&quot;">​</a></h3><p><a href="/04_people/沃伦·巴菲特.html">巴菲特</a>在1985年做出一个令华尔街震惊的决定：关闭<a href="/03_companies/伯克希尔哈撒韦.html">伯克希尔</a>·哈撒韦旗下运营了二十余年的纺织业务。</p><blockquote><p>&quot;我最大的遗憾之一，就是关闭纺织业务关得太晚。错在我自己，应该早点关。这个决定拖了很多年，浪费了大量资本。&quot; ——<a href="/04_people/沃伦·巴菲特.html">沃伦·巴菲特</a>，《<a href="/03_companies/伯克希尔哈撒韦.html">伯克希尔</a>·哈撒韦致股东信》，1985年</p></blockquote><p>这封信成为<a href="/04_people/沃伦·巴菲特.html">巴菲特</a>管理哲学的重要转折点：<strong>他承认自己曾因沉没成本和面子问题，迟迟不愿止损</strong>。此后，他更加坚定地将资本配置视为管理层的核心职能，并在评估任何业务时优先考虑&quot;人&quot;的因素。</p><hr><h3 id="_1986年-伯克希尔的两个核心工作" tabindex="-1">1986年｜伯克希尔的两个核心工作 <a class="header-anchor" href="#_1986年-伯克希尔的两个核心工作" aria-label="Permalink to &quot;1986年｜伯克希尔的两个核心工作&quot;">​</a></h3><p>1986年的致股东信中，<a href="/04_people/沃伦·巴菲特.html">巴菲特</a>用最简洁的语言概括了<a href="/04_people/查理·芒格.html">查理·芒格</a>和他本人的职责定位：</p><blockquote><p>&quot;查理和我只有两个工作：第一个，吸引出色经理人并激励他们像所有者一样思考；第二个，配置从保险业务流入的资本。我们只和喜欢、欣赏彼此的人合作。&quot; ——<a href="/04_people/沃伦·巴菲特.html">沃伦·巴菲特</a>，《<a href="/03_companies/伯克希尔哈撒韦.html">伯克希尔</a>·哈撒韦致股东信》，1986年</p></blockquote><p>这段话奠定了<a href="/03_companies/伯克希尔哈撒韦.html">伯克希尔</a>独特的管理架构：<strong>总部只管人和钱，业务完全下放</strong>。<a href="/04_people/沃伦·巴菲特.html">巴菲特</a>从不对子公司发号施令，而是充分授权，让专业的人做专业的事。</p><hr><h3 id="_1987年-好企业好管理层-最佳持有期限就是永远" tabindex="-1">1987年｜好企业好管理层，最佳持有期限就是永远 <a class="header-anchor" href="#_1987年-好企业好管理层-最佳持有期限就是永远" aria-label="Permalink to &quot;1987年｜好企业好管理层，最佳持有期限就是永远&quot;">​</a></h3><p>在1987年致股东信中，<a href="/04_people/沃伦·巴菲特.html">巴菲特</a>表达了他对优质管理层最理想的投资态度：</p><blockquote><p>&quot;对于好企业配上优秀管理层，我们最喜欢的持有期限就是——永远。&quot; ——<a href="/04_people/沃伦·巴菲特.html">沃伦·巴菲特</a>，《<a href="/03_companies/伯克希尔哈撒韦.html">伯克希尔</a>·哈撒韦致股东信》，1987年</p></blockquote><p>这句话的背景是：<a href="/04_people/沃伦·巴菲特.html">巴菲特</a>发现，当管理层足够优秀时，卖出股票反而是一种损失——没有什么能比&quot;把资金托付给值得信赖的人&quot;更让人安心。</p><hr><h3 id="_1988年-为什么不合格的ceo能稳坐位置" tabindex="-1">1988年｜为什么不合格的CEO能稳坐位置？ <a class="header-anchor" href="#_1988年-为什么不合格的ceo能稳坐位置" aria-label="Permalink to &quot;1988年｜为什么不合格的CEO能稳坐位置？&quot;">​</a></h3><p>1988年的信中，<a href="/04_people/沃伦·巴菲特.html">巴菲特</a>罕见地对美国企业界的CEO选拔机制提出了犀利批评：</p><blockquote><p>&quot;一个不合格的CEO，为什么往往能在位很久？因为公司业绩的衡量标准模糊，董事会成员不愿批评同僚，高管薪酬又与业绩脱钩——所以位置特别稳。&quot; ——<a href="/04_people/沃伦·巴菲特.html">沃伦·巴菲特</a>，《<a href="/03_companies/伯克希尔哈撒韦.html">伯克希尔</a>·哈撒韦致股东信》，1988年</p></blockquote><p>这段分析直指公司治理的结构性缺陷，也解释了为什么<a href="/04_people/沃伦·巴菲特.html">巴菲特</a>在<a href="/03_companies/伯克希尔哈撒韦.html">伯克希尔</a>内部坚持建立一套完全不同的激励与问责机制。</p><hr><h3 id="_1992年-所罗门危机——-我不是来当ceo的-我是来保护公司声誉的" tabindex="-1">1992年｜所罗门危机——&quot;我不是来当CEO的，我是来保护公司声誉的&quot; <a class="header-anchor" href="#_1992年-所罗门危机——-我不是来当ceo的-我是来保护公司声誉的" aria-label="Permalink to &quot;1992年｜所罗门危机——&quot;我不是来当CEO的，我是来保护公司声誉的&quot;&quot;">​</a></h3><p>1992年，<a href="/03_companies/所罗门兄弟.html">所罗门兄弟</a>公司因国债欺诈丑闻陷入生死存亡的危机。<a href="/04_people/沃伦·巴菲特.html">巴菲特</a>临危受命，担任临时董事长。他在危机最严重的时刻公开表示：</p><blockquote><p>&quot;我不是来当CEO的，我是来保护公司声誉的。信任和信誉是金融机构最重要的资产，一旦失去，几十年都未必能重建。&quot; ——<a href="/04_people/沃伦·巴菲特.html">沃伦·巴菲特</a>，所罗门兄弟危机处理，1992年</p></blockquote><p><a href="/04_people/沃伦·巴菲特.html">巴菲特</a>在短短几周内稳定了局面，亲自向美国财政部和公众重建信任。这一事件进一步印证了他的核心信念：<strong>声誉是商业最重要的无形资产，破坏它可能只需一瞬间，修复它却需要几十年甚至几个世纪</strong>。</p><hr><h3 id="_1996年-经理人就是所有者-完全放心" tabindex="-1">1996年｜经理人就是所有者，完全放心 <a class="header-anchor" href="#_1996年-经理人就是所有者-完全放心" aria-label="Permalink to &quot;1996年｜经理人就是所有者，完全放心&quot;">​</a></h3><p>1996年的致股东信中，<a href="/04_people/沃伦·巴菲特.html">巴菲特</a>对<a href="/03_companies/伯克希尔哈撒韦.html">伯克希尔</a>旗下经理人给出了极高的评价：</p><blockquote><p>&quot;我们的经理人就是像所有者一样思考，完全放心。我们不需要打卡，不需要审批，不需要层层汇报——他们本身就是主人翁。&quot; ——<a href="/04_people/沃伦·巴菲特.html">沃伦·巴菲特</a>，《<a href="/03_companies/伯克希尔哈撒韦.html">伯克希尔</a>·哈撒韦致股东信》，1996年</p></blockquote><p><a href="/04_people/沃伦·巴菲特.html">巴菲特</a>将这种文化归功于<a href="/03_companies/伯克希尔哈撒韦.html">伯克希尔</a>独特的激励机制：<strong>他给予经理人充分的信任和自主权，同时在利益上真正与股东绑定</strong>。这套机制运行至今，让<a href="/03_companies/伯克希尔哈撒韦.html">伯克希尔</a>旗下聚集了全球最优秀的一批企业家。</p><hr><h3 id="_2008年-信任是商业的基石" tabindex="-1">2008年｜信任是商业的基石 <a class="header-anchor" href="#_2008年-信任是商业的基石" aria-label="Permalink to &quot;2008年｜信任是商业的基石&quot;">​</a></h3><p>2008年全球金融危机期间，<a href="/04_people/沃伦·巴菲特.html">巴菲特</a>在致股东信中写下了他对金融体系最深刻的反思：</p><blockquote><p>&quot;信任是商业的基础。破坏它需要几十年，修复它可能需要几百年。一旦信任崩塌，整个体系都将受到冲击。&quot; ——<a href="/04_people/沃伦·巴菲特.html">沃伦·巴菲特</a>，《<a href="/03_companies/伯克希尔哈撒韦.html">伯克希尔</a>·哈撒韦致股东信》，2008年</p></blockquote><p>金融危机让无数金融机构因信任危机而崩塌，<a href="/04_people/沃伦·巴菲特.html">巴菲特</a>以他在所罗门危机的亲身经历警告：<strong>管理层最重要的职责之一，就是维护公司的信任资产</strong>。这段话在2008年金融危机后被广泛引用，成为公司治理领域的经典论述。</p><hr><h3 id="_2014年-优秀管理层是收购溢价的核心原因" tabindex="-1">2014年｜优秀管理层是收购溢价的核心原因 <a class="header-anchor" href="#_2014年-优秀管理层是收购溢价的核心原因" aria-label="Permalink to &quot;2014年｜优秀管理层是收购溢价的核心原因&quot;">​</a></h3><p>在2014年致股东信中，<a href="/04_people/沃伦·巴菲特.html">巴菲特</a>坦诚地解释了<a href="/03_companies/伯克希尔哈撒韦.html">伯克希尔</a>为何愿意为优质企业支付高于账面价值的收购价格：</p><blockquote><p>&quot;我们支付收购溢价，唯一合理的解释就是优秀管理层——他们是<a href="/03_companies/伯克希尔哈撒韦.html">伯克希尔</a>收购溢价的核心原因。&quot; ——<a href="/04_people/沃伦·巴菲特.html">沃伦·巴菲特</a>，《<a href="/03_companies/伯克希尔哈撒韦.html">伯克希尔</a>·哈撒韦致股东信》，2014年</p></blockquote><p><a href="/04_people/沃伦·巴菲特.html">巴菲特</a>指出，买一家工厂、一块土地很容易定价，但<strong>优秀的管理层和文化是无法用金钱复制的资产</strong>，这才是他愿意支付溢价收购真正的理由。</p><hr><h2 id="为什么管理层如此重要" tabindex="-1">为什么管理层如此重要？ <a class="header-anchor" href="#为什么管理层如此重要" aria-label="Permalink to &quot;为什么管理层如此重要？&quot;">​</a></h2><p><a href="/04_people/沃伦·巴菲特.html">巴菲特</a>曾多次在致股东信中阐述一个核心观点：<strong>投资一家公司，本质上是投资这家公司背后的人</strong>。同样的资产，在不同管理水平下，可以产生天壤之别的回报。</p><blockquote><p>&quot;我们收购的不是工厂和机器——工厂和机器可以复制。我们收购的是人，以及这些人所代表的文化、能力和诚信。&quot;<br> ——<a href="/04_people/沃伦·巴菲特.html">沃伦·巴菲特</a>，《<a href="/03_companies/伯克希尔哈撒韦.html">伯克希尔</a>·哈撒韦致股东信》，1983年</p></blockquote><p>这个认知贯穿了<a href="/04_people/沃伦·巴菲特.html">巴菲特</a>六十余年的投资生涯。他不仅是一位伟大的投资者，更是一位识人、用人、爱才的伯乐。</p><hr><h2 id="巴菲特选择管理层的标准" tabindex="-1">巴菲特选择管理层的标准 <a class="header-anchor" href="#巴菲特选择管理层的标准" aria-label="Permalink to &quot;巴菲特选择管理层的标准&quot;">​</a></h2><h3 id="标准一-诚信——不可撼动的底线" tabindex="-1">标准一：诚信——不可撼动的底线 <a class="header-anchor" href="#标准一-诚信——不可撼动的底线" aria-label="Permalink to &quot;标准一：诚信——不可撼动的底线&quot;">​</a></h3><p>在<a href="/04_people/沃伦·巴菲特.html">巴菲特</a>的管理层评估体系中，<strong>诚信是唯一不可妥协的标准</strong>。没有诚信，无论能力多强，都是不值得信任的人。</p><blockquote><p>&quot;我们在评估管理层时，首先问一个问题：如果我知道他们明天就会离开，我还会不会愿意把资金托付给他们？如果答案是否定的，那就一票否决。&quot;<br> ——<a href="/04_people/沃伦·巴菲特.html">沃伦·巴菲特</a>，《<a href="/03_companies/伯克希尔哈撒韦.html">伯克希尔</a>·哈撒韦致股东信》，1996年</p></blockquote><p><a href="/04_people/沃伦·巴菲特.html">巴菲特</a>的诚信测试标准极为严格：他期望管理层像对待自己的钱一样对待股东的钱，像对待自己的家人一样对待客户和员工。</p><h3 id="标准二-理性——资本配置的智慧" tabindex="-1">标准二：理性——资本配置的智慧 <a class="header-anchor" href="#标准二-理性——资本配置的智慧" aria-label="Permalink to &quot;标准二：理性——资本配置的智慧&quot;">​</a></h3><p><a href="/04_people/沃伦·巴菲特.html">巴菲特</a>的第二个核心标准是<strong>理性</strong>——管理层是否具备良好的资本配置能力，以及是否在做决策时保持理性而非被私心或面子所驱动。</p><blockquote><p>&quot;一家理性的公司，管理层会坦诚地告诉股东公司的真实状况；会把所有选项摆在桌面上讨论；会在资本配置时始终以股东利益为导向。&quot;<br> ——<a href="/04_people/沃伦·巴菲特.html">沃伦·巴菲特</a>，《<a href="/03_companies/伯克希尔哈撒韦.html">伯克希尔</a>·哈撒韦致股东信》，1996年</p></blockquote><h3 id="标准三-独立思考——不被华尔街左右" tabindex="-1">标准三：独立思考——不被华尔街左右 <a class="header-anchor" href="#标准三-独立思考——不被华尔街左右" aria-label="Permalink to &quot;标准三：独立思考——不被华尔街左右&quot;">​</a></h3><p><a href="/04_people/沃伦·巴菲特.html">巴菲特</a>特别看重管理层是否具备<strong>独立思考的能力</strong>，而不被华尔街分析师、机构投资者或短期股价波动所左右。</p><blockquote><p>&quot;华尔街会给你压力，让你做很多看起来合理但实际上在摧毁价值的事情。真正优秀的 CEO ，是那些能够在压力下保持独立判断，不为短期舆论所动的人。&quot;<br> ——<a href="/04_people/沃伦·巴菲特.html">沃伦·巴菲特</a>，《<a href="/03_companies/伯克希尔哈撒韦.html">伯克希尔</a>·哈撒韦致股东信》，2000年</p></blockquote><hr><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p><a href="/04_people/沃伦·巴菲特.html">巴菲特</a>选择管理层的标准，看似朴素，实则深刻——诚信、理性、独立思考。这三个标准共同构成了他对管理层的完整画像。</p><p>从1970年代强调&quot;找到出色经理人&quot;，到1980年代躬身反思纺织业务的失误，再到2008年金融危机中重申&quot;信任是商业的基石&quot;——他的管理哲学始终如一：<strong>投资的核心是投人，投人的核心是投信任</strong>。</p><p>对于普通投资者而言，理解这些原则不仅仅是为了筛选股票，更是一种值得借鉴的识人智慧：无论是选择合作伙伴、投资对象，还是在职场中选择追随的领导，这些原则都有其普适价值。</p><p><strong>跟对人，是投资成功的第一步——也是最重要的一步。</strong></p>',72)])])}const q=t(r,[["render",h]]);export{u as __pageData,q as default};
